    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i + 1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            pivot = A[i][i]
            for j in range(n):
                A[i][j] /= pivot
            for j in range(m):
                if j != i:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        return A

    def matrix_mult(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0] * p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def isomorphism_rank(phi, q):
        n = len(phi)
        G = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n):
            for j in range(n):
                if phi[i][j]:
                    G[i][j] = 1
                    G[j][i] = 1
        G[n][n] = 1
        rank = gaussian_elimination(G)
        return sum(1 for row in rank if any(row))

    def cnf_formula(n):
        literals = [random.randint(0, 1) for _ in range(n)]
        clauses = []
        for i in range(n):
            clause = []
            for j in range(n):
                if random.choice([True, False]):
                    clause.append((i, literals[j]))
                else:
                    clause.append((j, literals[i]))
            clauses.append(clause)
        return literals, clauses

    def circuit_size(phi):
        n = len(phi)
        size = 0
        for clause in phi[1]:
            size += len(clause)
        return size

    n_max = 40
    instances_tested = 30
    metric_values = []
    conjecture_holds = True
    counterexample = ""

